"""Generate the Databricks notebook 20_core_forecast_alloc.py from fc_sql.py + fc_engine.py (single source of truth)."""
import os
F = os.path.dirname(os.path.abspath(__file__))
sql = open(f"{F}/fc_sql.py").read()
eng = open(f"{F}/fc_engine.py").read().replace("from __future__ import annotations\n", "")
drv = open(f"{F}/_driver.py").read()
nb = ("# Databricks notebook source\n# MAGIC %md\n# MAGIC # 20 · CORE forecast + allocation (dev)\n"
      "# MAGIC Generated by build_notebook.py from fc_sql.py + fc_engine.py + _driver.py — edit those, not this file.\n\n"
      "# COMMAND ----------\n" + sql + "\n\n# COMMAND ----------\n" + eng + "\n" + drv)
open(f"{F}/20_core_forecast_alloc.py", "w").write(nb)
print("written", len(nb.splitlines()), "lines")
